/**
 * Represents an active model available in the AI Horde.
 * Based on the API response from /v2/status/models
 */
export interface ActiveModel {
  /** The name of the model. */
  name: string;
  /** How many workers are running this model. */
  count: number;
  /** The average speed of generation for this model. */
  performance?: number;
  /** The amount waiting to be generated by this model. */
  queued?: number;
  /** The job count waiting to be generated by this model. */
  jobs?: number;
  /** Estimated time in seconds for this model's queue to be cleared. */
  eta?: number;
  /** The model type (text or image). */
  type?: 'image' | 'text';
  /** True for custom models, false for known models; absent when unclassified. */
  custom?: boolean;
  /** Present only on the text list requested with `chat=true`. */
  chat?: ModelChatSummary;
}

/** A combined summary of the online chat workers serving one text model. */
export interface ModelChatSummary {
  /** How many online chat workers serve the model. */
  workers: number;
  /** The largest chat context among those workers. */
  max_context_length: number;
  /** The largest chat reply among those workers. */
  max_length: number;
  /** The sorted union of the workers' features, guarantees included. */
  features: string[];
  created: number;
}

/** Type of model: image or text */
export type ModelType = 'image' | 'text';

/** A short sentence to print, named by its translation key. */
export interface ModelEtaLabel {
  key: string;
  params: Record<string, string | number>;
}

/** Below this many seconds the wait is spoken in seconds rather than minutes. */
const ETA_MINUTES_FROM_SECONDS = 90;

/**
 * How long the horde says this model's queue will take to clear, short enough
 * to sit on one row of a picker. It is the horde's own estimate rather than a
 * promise, which the copy says.
 *
 * Null when nobody is carrying the model: the horde still reports an eta for a
 * model with no workers, and that number means nothing.
 */
export function modelEtaLabel(model: ActiveModel): ModelEtaLabel | null {
  if (model.count === 0) {
    return null;
  }
  const eta = model.eta;
  if (typeof eta !== 'number' || !Number.isFinite(eta) || eta <= 0) {
    return { key: 'model_autocomplete.eta_none', params: {} };
  }
  return eta < ETA_MINUTES_FROM_SECONDS
    ? {
        key: 'model_autocomplete.eta_seconds',
        params: { seconds: Math.max(1, Math.round(eta)) },
      }
    : {
        key: 'model_autocomplete.eta_minutes',
        params: { minutes: Math.round(eta / 60) },
      };
}

/**
 * The list every model picker offers, built from the official model reference
 * with the horde's live worker counts laid over it.
 *
 * The reference is the universe of models: one with nobody serving it stays
 * selectable at a count of zero, so the picker does not empty out when the
 * network is quiet. A model a worker offers that the reference has never heard
 * of is a custom model and is folded in, marked so the picker can say as much.
 *
 * `referenceNames` is null until the reference answers, and the status list is
 * served on its own in the meantime rather than showing nothing.
 * Text callers disable `inferCustom`: only the backend can establish whether
 * its own reference recognizes a live text name for pricing.
 */
export function mergeModelList(
  referenceNames: readonly string[] | null,
  statusModels: readonly ActiveModel[],
  inferCustom = true,
): ActiveModel[] {
  const byName = new Map<string, ActiveModel>();
  for (const model of statusModels) {
    if (model.name) {
      byName.set(model.name, model);
    }
  }

  const merged: ActiveModel[] =
    referenceNames === null
      ? [...byName.values()]
      : referenceNames
          .filter((name) => name !== '')
          .map((name) => byName.get(name) ?? { name, count: 0 });

  if (referenceNames !== null) {
    const known = new Set(referenceNames);
    for (const model of byName.values()) {
      if (!known.has(model.name)) {
        merged.push(
          inferCustom && model.custom === undefined
            ? { ...model, custom: true }
            : model,
        );
      }
    }
  }

  return merged.sort(
    (a, b) => b.count - a.count || a.name.localeCompare(b.name),
  );
}
